from docx import Document
from docx.shared import Inches, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
path='output/spa-markup-memorandum.docx'
doc=Document(path)
sec=doc.sections[0]
for attr,val in [('top_margin',0.7),('bottom_margin',0.7),('left_margin',0.8),('right_margin',0.8)]: setattr(sec,attr,Inches(val))
styles=doc.styles
styles['Normal'].font.name='Arial'; styles['Normal']._element.rPr.rFonts.set(qn('w:eastAsia'),'Arial'); styles['Normal'].font.size=Pt(9.5); styles['Normal'].paragraph_format.space_after=Pt(4); styles['Normal'].paragraph_format.line_spacing=1.05
for name,size in [('Title',18),('Heading 1',14),('Heading 2',11.5),('Heading 3',10.5)]:
    if name in styles:
        st=styles[name]; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Arial'); st.font.size=Pt(size); st.font.bold=True; st.paragraph_format.space_before=Pt(10 if name!='Title' else 0); st.paragraph_format.space_after=Pt(5)
header=sec.header.paragraphs[0]; header.text='PRIVILEGED AND CONFIDENTIAL — ATTORNEY WORK PRODUCT'; header.alignment=WD_ALIGN_PARAGRAPH.RIGHT
for r in header.runs: r.font.name='Arial'; r.font.size=Pt(8); r.font.italic=True
footer=sec.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=footer.add_run('Project Cascade  |  SPA Markup Memorandum  |  '); r.font.name='Arial'; r.font.size=Pt(8); fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); footer._p.append(fld)
for p in doc.paragraphs:
    if p.text.strip().startswith('PRIVILEGED AND CONFIDENTIAL'):
        p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        for run in p.runs: run.font.bold=True; run.font.size=Pt(10)
    if p.style.name.startswith('Heading'): p.paragraph_format.keep_with_next=True
for table in doc.tables:
    for row_i,row in enumerate(table.rows):
        if row_i==0:
            trPr=row._tr.get_or_add_trPr(); tblHeader=OxmlElement('w:tblHeader'); tblHeader.set(qn('w:val'),'true'); trPr.append(tblHeader)
        for cell in row.cells:
            for p in cell.paragraphs:
                for run in p.runs: run.font.name='Arial'; run.font.size=Pt(8)
props=doc.core_properties; props.title='SPA Markup Memorandum — Project Cascade'; props.subject='Buyer-side markup memorandum for Cascadia Environmental Solutions stock purchase agreement'; props.author='Ashford, Pennington & Yates LLP'; props.comments='Privileged and confidential attorney work product.'
doc.save(path)
PY
parse-doc docx output/spa-markup-memorandum.docx > memo-validate.txt 2> memo-validate.err
printf 'docx bytes: '; wc -c < output/spa-markup-memorandum.docx
printf 'parsed lines: '; wc -l < memo-validate.txt
printf 'parse stderr bytes: '; wc -c < memo-validate.err","description":"Regenerate and revalidate memorandum DOCX","timeoutMs":120000}

